/**
 * Unit tests for CategoryPlot.removeDomainMarker.
 */
public class CategoryPlot_removeDomainMarker_TriageGen0Test {

    private CategoryPlot plot;
    private Marker mockMarker;

    @Before
    public void setUp() {
        plot = new CategoryPlot();
        mockMarker = mock(Marker.class);
    }

    /**
     * Helper method to inject markers into the private fields of CategoryPlot using reflection,
     * since the class does not provide public setters for the internal marker lists.
     */
    @SuppressWarnings("unchecked")
    private void setMarkers(Layer layer, int index, ArrayList<Marker> markers) throws Exception {
        String fieldName = (layer == Layer.FOREGROUND) ? "foregroundDomainMarkers" : "backgroundDomainMarkers";
        Field field = CategoryPlot.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        Map<Integer, ArrayList<Marker>> map = (Map<Integer, ArrayList<Marker>>) field.get(plot);
        if (map == null) {
            map = new HashMap<>();
            field.set(plot, map);
        }
        map.put(index, markers);
    }

    @Test
    public void testRemoveDomainMarker_Foreground_Success() throws Exception {
        int index = 0;
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(mockMarker);
        setMarkers(Layer.FOREGROUND, index, markers);

        boolean result = plot.removeDomainMarker(index, mockMarker, Layer.FOREGROUND, true);

        assertTrue("Marker should be removed successfully", result);
        assertTrue("Marker list should be empty", markers.isEmpty());
    }

    @Test
    public void testRemoveDomainMarker_Background_Success() throws Exception {
        int index = 0;
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(mockMarker);
        setMarkers(Layer.BACKGROUND, index, markers);

        boolean result = plot.removeDomainMarker(index, mockMarker, Layer.BACKGROUND, true);

        assertTrue("Marker should be removed successfully", result);
        assertTrue("Marker list should be empty", markers.isEmpty());
    }

    @Test
    public void testRemoveDomainMarker_NotFound() throws Exception {
        int index = 0;
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(mock(Marker.class)); // Different marker
        setMarkers(Layer.FOREGROUND, index, markers);

        boolean result = plot.removeDomainMarker(index, mockMarker, Layer.FOREGROUND, true);

        assertFalse("Should return false when marker is not in list", result);
        assertEquals("List size should remain 1", 1, markers.size());
    }

    @Test
    public void testRemoveDomainMarker_NotifyFalse() throws Exception {
        int index = 0;
        ArrayList<Marker> markers = new ArrayList<>();
        markers.add(mockMarker);
        setMarkers(Layer.FOREGROUND, index, markers);

        // notify is false, so fireChangeEvent should not be triggered (though we can't easily verify 
        // fireChangeEvent without a spy, we verify the return value and state).
        boolean result = plot.removeDomainMarker(index, mockMarker, Layer.FOREGROUND, false);

        assertTrue("Should return true even if notify is false", result);
        assertTrue("Marker should still be removed", markers.isEmpty());
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testRemoveDomainMarker_InvalidIndex() throws Exception {
        // Attempting to access an index that doesn't exist in the map
        plot.removeDomainMarker(99, mockMarker, Layer.FOREGROUND, true);
    }
}
